questionvariables.text:
/* helpers: relation tokens, display strings, inequality builders */
relt(r) := if r="lt" then "\\lt" else if r="le" then "\\le" else if r="gt" then "\\gt" else "\\ge";
reluc(r) := if r="lt" then "<" else if r="le" then "≤" else if r="gt" then ">" else "≥";
relflip(r) := if r="lt" then "gt" else if r="le" then "ge" else if r="gt" then "lt" else "le";
relother(r) := if r="lt" then "le" else if r="le" then "lt" else if r="gt" then "ge" else "gt";
relcomp(r) := if r="lt" then "ge" else if r="le" then "gt" else if r="gt" then "le" else "lt";
strictp(r) := is(r="lt" or r="gt");
/* Typed answers must be one inequality; "and"/"or" statements are rejected at validation. */
vsingle(ex) := if not atom(ex) and member(op(ex), ["and", "or", "nounand", "nounor"]) then "Type a single inequality, without the words and or or." else "";
mkin(u, r, w) := if r="lt" then u<w else if r="le" then u<=w else if r="gt" then u>w else u>=w;
holds(u, r, w) := if r="lt" then is(u<w) else if r="le" then is(u<=w) else if r="gt" then is(u>w) else is(u>=w);
relopts(c) := [["lt",is(c="lt"),"<"],["le",is(c="le"),"≤"],["gt",is(c="gt"),">"],["ge",is(c="ge"),"≥"]];
termp(v) := block([dd], dd: denom(v), while is(mod(dd,2)=0) do dd: dd/2, while is(mod(dd,5)=0) do dd: dd/5, is(dd=1));
nd(v) := if integerp(v) then string(v) else if termp(v) then string(float(v))
  else sconcat(if is(v<0) then "-" else "", "\\frac{", string(abs(num(v))), "}{", string(denom(v)), "}");
ndm(v) := sconcat("\\(", nd(v), "\\)");
/* plain-text number for aria-labels (nd gives TeX fractions, which a screen reader reads raw) */
ndt(v) := if integerp(v) then string(v) else if termp(v) then string(float(v)) else sconcat(string(num(v)), "/", string(denom(v)));
trm(k, v, fst) := block([m, s], m: abs(k), s: if v="" then nd(m) else if m=1 then v else sconcat(nd(m), v),
  if fst then (if k<0 then sconcat("-", s) else s) else (if k<0 then sconcat(" - ", s) else sconcat(" + ", s)));
lfs(L) := block([s, t], s: "", for t in L do (if t[1]#0 then s: sconcat(s, trm(t[1], t[2], is(s="")))), if s="" then "0" else s);
ins(a, b, c, r) := sconcat(lfs([[a,"x"],[b,"y"]]), " ", relt(r), " ", nd(c));
ineqd(a, b, c, r) := sconcat("\\(", ins(a, b, c, r), "\\)");
lind(a, b, c) := sconcat("\\(", lfs([[a,"x"],[b,"y"]]), " = ", nd(c), "\\)");
ineqm(a, b, c, r) := mkin(a*x+b*y, r, c);
/* Design: solve a combined inequality and give integer values. Source: adapted from SMP GCSE Higher 1, Chapter 28, questions F5 and F6.
   q14 [p,a,b,q,rel1,rel2]: p rel1 a*x+b rel2 q. Every entry has one strict and one inclusive end,
   so the swapped-ends diagnostic exists on every seed; four entries have a < 0. Answers computed here, not copied. */
q14: [[-12,-4,8,16,"le","lt"],[6,-2,4,12,"le","lt"],[5,-5,5,20,"le","lt"],[1,-2,9,9,"le","lt"],[19,5,9,34,"le","lt"],[15,6,9,33,"lt","le"],[-10,3,2,8,"lt","le"],[0,2,2,10,"lt","le"],[-6,5,-6,9,"lt","le"],[-30,5,-5,0,"le","lt"]];
ix: 1+rand(10);
p: q14[ix][1]; a: q14[ix][2]; b: q14[ix][3]; q: q14[ix][4]; rel1: q14[ix][5]; rel2: q14[ix][6];
lo: if is(a>0) then (p-b)/a else (q-b)/a;
hi: if is(a>0) then (q-b)/a else (p-b)/a;
lc: if is(a>0) then is(rel1="le") else is(rel2="le");
rc: if is(a>0) then is(rel2="le") else is(rel1="le");
cnt: (if rc then floor(hi) else ceiling(hi)-1) - (if lc then ceiling(lo) else floor(lo)+1) + 1;
outer: sort([p/a, q/a]);
lsg: if lc then "le" else "lt"; rsg: if rc then "le" else "lt";
o2: relopts(lsg); o3: relopts(rsg);
/* test values */
dlsg: if rc then "ge" else "gt"; drsg: if lc then "ge" else "gt";
xlsg: if lc then "lt" else "le"; xrsg: if rc then "lt" else "le";
c1: cnt+1; c3: cnt+3; c5: cnt+5; cm1: cnt-1;
olo: outer[1]; ohi: outer[2]; lom: lo-1; hip: hi+2;
pd: sconcat("\\(", nd(p), " ", relt(rel1), " ", lfs([[a,"x"],[b,""]]), " ", relt(rel2), " ", nd(q), "\\)");
ansd: sconcat("\\(", nd(lo), " ", relt(lsg), " x ", relt(rsg), " ", nd(hi), "\\)");
ints: makelist(k, k, if lc then lo else lo+1, if rc then hi else hi-1);

feedbackvariables.text:
up: is(member(ans2, ["lt","le"]) and member(ans3, ["lt","le"]));
dn: is(member(ans2, ["gt","ge"]) and member(ans3, ["gt","ge"]));
samedir: is(up or dn);
llo: if up then ans1 else ans4;
lhi: if up then ans4 else ans1;
llc: if up then is(ans2="le") else is(ans3="ge");
lrc: if up then is(ans3="le") else is(ans2="ge");
endsok: is(abs(llo-lo) < 1/1000 and abs(lhi-hi) < 1/1000);
match: is(endsok and is(llc = lc) and is(lrc = rc));
swapped: is(llc = rc and lrc = lc);
outerok: is(abs(llo-outer[1]) < 1/1000 and abs(lhi-outer[2]) < 1/1000);

up: is(member(ans2, ["lt","le"]) and member(ans3, ["lt","le"]));
dn: is(member(ans2, ["gt","ge"]) and member(ans3, ["gt","ge"]));
samedir: is(up or dn);
llo: if up then ans1 else ans4;
lhi: if up then ans4 else ans1;
llc: if up then is(ans2="le") else is(ans3="ge");
lrc: if up then is(ans3="le") else is(ans2="ge");
endsok: is(abs(llo-lo) < 1/1000 and abs(lhi-hi) < 1/1000);
match: is(endsok and is(llc = lc) and is(lrc = rc));
ilo: if llc then ceiling(llo) else floor(llo)+1;
ihi: if lrc then floor(lhi) else ceiling(lhi)-1;
ftc: if samedir then max(0, ihi-ilo+1) else -1;
ftb: if samedir then ihi else -1000;
